    private bool IsActive(string? path)
    {
        if (string.IsNullOrWhiteSpace(path)) return false;
        return string.Equals(CurrentPath, "/" + path.Split('?')[0].Split('#')[0].Trim('/'), StringComparison.OrdinalIgnoreCase);
    }

    private bool IsParentMenuActive(MenuItemDto menu)
    {
        return menu?.children?.Any(c => !string.IsNullOrWhiteSpace(c?.url) && IsActive(c.url)) ?? false;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _module = await JsRuntime.InvokeAsync<IJSObjectReference>("import", "./js/pages/custom-table.js");
            await JsRuntime.InvokeVoidAsync("loadCustomTable");
            await JsRuntime.InvokeVoidAsync("loadConfig");
            await JsRuntime.InvokeVoidAsync("loadApps");
        }
    }

    private async Task ToggleOnHoverSidebar()
    {
        await JsRuntime.InvokeVoidAsync("toggleOnHoverSidebar");
    }

    public void Dispose()
    {
        NavigationManager.LocationChanged -= OnLocationChanged;
    }

    private string FindTitleForCurrentPath()
    {
        foreach (var menu in menus)
        {
            if (IsActive(menu.url))
                return menu.title;

            if (menu.children != null)
            {
                var match = menu.children.FirstOrDefault(c => IsActive(c.url));
                if (match != null)
                    return match.title;
            }
        }
        return "Reconciliation Management System";
    }

    private void OpenMenu(MenuItemDto submenu)
    {
        MenuNavigationService.SetMenu(submenu.title!);
    }

